from collections import Counter

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    for r in range(1, rows - 1):
        if len(set(grid[r])) == 1:
            divider = grid[r][0]
            if any(divider in row for row in grid[:r] + grid[r + 1:]):
                continue
            top = grid[:r]
            bottom = grid[r + 1:]
            return compare_panels(top, bottom)

    for c in range(1, cols - 1):
        divider = grid[0][c]
        if all(row[c] == divider for row in grid):
            if any(row[j] == divider for row in grid for j in range(cols) if j != c):
                continue
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            return compare_panels(left, right)

    return [row[:] for row in grid]


def compare_panels(first, second):
    first_colors = {v for row in first for v in row}
    second_colors = {v for row in second for v in row}
    shared = first_colors & second_colors
    if len(shared) == 1:
        background = next(iter(shared))
    else:
        background = Counter(v for row in first for v in row).most_common(1)[0][0]
    return [[3 if a == b else background for a, b in zip(row_a, row_b)]
            for row_a, row_b in zip(first, second)]
